INSERT INTO `v1_5b2831a3eb9f8aaa2bec58be2915b4ddea574a3b2a633fc098650e4846dddf40` VALUES ("フリーマーケットを訪れたジータが出会ったのは\n城をこっそり抜け出していたペコリーヌだった。", 20063115, 2834, 7, 10118, 91002, 2, 1, 8, 5118061, "ペコリーヌとの出会い", 40, "青空の下で謁見", 0, "フリーマーケット会場");
INSERT INTO `v1_5b2831a3eb9f8aaa2bec58be2915b4ddea574a3b2a633fc098650e4846dddf40` VALUES ("ジータたちがフリーマーケットを巡っていると\n露店を出していたマホに声をかけられる。", 20063115, 2835, 7, 10118, 91002, 2, 1, 8, 5118062, "マホとの出会い", 40, "未来の騎空団\nマスコット？", 0, "フリーマーケット会場");
INSERT INTO `v1_5b2831a3eb9f8aaa2bec58be2915b4ddea574a3b2a633fc098650e4846dddf40` VALUES ("ジータが騎空団への依頼を確認していると、\n高笑いをしながらアキノが現れる。", 20063115, 2837, 7, 10118, 91002, 2, 1, 8, 5118063, "アキノとの出会い", 40, "お嬢さまからの\n緊急依頼", 0, "ランドソル市街地");
INSERT INTO `v1_5b2831a3eb9f8aaa2bec58be2915b4ddea574a3b2a633fc098650e4846dddf40` VALUES ("ジータたちは、フリーマーケット会場で\n少し困った様子のジュンを見かける。", 20063115, 4108402, 18, 10118, 91002, 2, 1, 8, 5118064, "ジュンとの出会い", 40, "黄金色の悩みごと", 0, "フリーマーケット会場");
INSERT INTO `v1_5b2831a3eb9f8aaa2bec58be2915b4ddea574a3b2a633fc098650e4846dddf40` VALUES ("フリーマーケットの隅で開かれる格闘大会──\nそこにはカオリもいて……？", 20063115, 4107402, 18, 10118, 91002, 2, 1, 8, 5118065, "カオリとの出会い", 40, "白熱！　格闘大会！", 0, "フリーマーケット会場");
INSERT INTO `v1_5b2831a3eb9f8aaa2bec58be2915b4ddea574a3b2a633fc098650e4846dddf40` VALUES ("太鼓祭を控えるオーエド町──\nジータは、困った様子のニノンと出会う。", 20063115, 9000227, 16, 10118, 91002, 2, 1, 8, 5118066, "ニノンとの出会い", 40, "祭り太鼓はオーエドの華", 1, "オーエド町");
INSERT INTO `v1_5b2831a3eb9f8aaa2bec58be2915b4ddea574a3b2a633fc098650e4846dddf40` VALUES ("ビカラはイベントに出演中のスズナを見かける。\nしかし、スズナはどこか困っているようで……？", 20063115, 2101181, 19, 10118, 91002, 3, 1, 8, 5118067, "スズナとの出会い", 40, "人気者は遅れて\nやってくる", 0, "フリーマーケット会場");
INSERT INTO `v1_5b2831a3eb9f8aaa2bec58be2915b4ddea574a3b2a633fc098650e4846dddf40` VALUES ("ビカラたちが街を散策していると、通りかかった\nナナカが興奮した様子で近づいてきて……？", 20063115, 4109402, 18, 10118, 91002, 3, 1, 8, 5118068, "ナナカとの出会い", 40, "巫女・ミーツ・魔法少女", 0, "ランドソル市街地");
INSERT INTO `v1_5b2831a3eb9f8aaa2bec58be2915b4ddea574a3b2a633fc098650e4846dddf40` VALUES ("ネズ耳をなくしてしまい絶望するビカラ。同じ頃\nキャルとコッコロは落とし物を拾っており……", 20063115, 4305402, 18, 10118, 91002, 3, 1, 8, 5118069, "キャル＆コッコロとの出会い", 40, "ネズ耳は二度なくなる", 0, "フリーマーケット会場");
INSERT INTO `v1_5b2831a3eb9f8aaa2bec58be2915b4ddea574a3b2a633fc098650e4846dddf40` VALUES ("街外れでひと休みをしていたビカラたちは、\nすっかりゴキゲンな様子のユカリと出会う。", 20063115, 4101402, 18, 10118, 91002, 3, 1, 8, 5118070, "ユカリとの出会い", 40, "この出会いにカンパイ！", 0, "ランドソル市街地");
INSERT INTO `v1_5b2831a3eb9f8aaa2bec58be2915b4ddea574a3b2a633fc098650e4846dddf40` VALUES ("ビカラは、人混みに怯えるアオイを心配し、\n陽気に声をかけるも……", 20063115, 4106402, 18, 10118, 91002, 3, 1, 8, 5118071, "アオイとの出会い", 40, "陰陽アンサンブル", 0, "ランドソル市街地");
INSERT INTO `v1_5b2831a3eb9f8aaa2bec58be2915b4ddea574a3b2a633fc098650e4846dddf40` VALUES ("ビカラがフリーマーケット会場を歩いていると\n占いをしていたシノブに声をかけられる。", 20063115, 2836, 7, 10118, 91002, 3, 1, 8, 5118072, "シノブとの出会い", 40, "運試し十番勝負！", 1, "フリーマーケット会場");
INSERT INTO `v1_5b2831a3eb9f8aaa2bec58be2915b4ddea574a3b2a633fc098650e4846dddf40` VALUES (0, 20063115, 0, 0, 10118, 0, 1, 0, 0, 5118600, "オープニング", 0, "彼女たちの新たな日常", 0, 0);
